# Spec 002, G6/R8: setting a password through a one-time link generated by an admin.
# The token travels as a query or form parameter (never in the path), so it is filtered from logs
# and from the audit log (spec 003).
class PasswordResetsController < ApplicationController
  layout "auth" # spec 006: centered sign-in card, no navigation
  allow_unauthenticated_access
  rate_limit to: 10, within: 3.minutes, only: :update, store: RATE_LIMIT_STORE,
             with: -> { redirect_to new_session_path, alert: "Too many attempts. Try again in a few minutes." }
  before_action :set_link

  def show
  end

  def update
    Current.actor = "password-link:#{@link.user.id}:#{@link.user.username}" # the link holder sets the password
    if @link.redeem!(password: params[:password], password_confirmation: params[:password_confirmation])
      terminate_session
      redirect_to new_session_path, notice: "Password set. You can sign in now."
    else
      @errors = @link.user.errors.full_messages
      render :show, status: :unprocessable_content
    end
  end

  private

  def set_link
    @token = params[:token].to_s
    @link = PasswordLink.find_usable(@token)
    render :invalid, status: :not_found unless @link
  end
end
